theorem findIdxs_cons :
    (x :: xs : List α).findIdxs p s =
    if p x then s :: xs.findIdxs p (s + 1) else xs.findIdxs p (s + 1)

theorem take_succ_drop {l : List α} {n stop : Nat}
    (h : n < l.length - stop) :
    (l.drop stop |>.take (n + 1)) = (l.drop stop |>.take n) ++ [l[stop + n]'(by omega)]

theorem getElem_swap {xs : List α} {i j k : Nat}
    (hk : k < (xs.swap i j).length) : (xs.swap i j)[k] =
    if h₁ : k = i ∧ j < xs.length then xs[j] else if h₂ : k = j ∧ i < xs.length then xs[i]
    else xs[k]'(length_swap ▸ hk)

theorem coe_idxInj [BEq α] [ReflBEq α] {xs ys : List α} {h : xs <+~ ys}
    {i : Fin xs.length} :
    (h.idxInj i : Nat) = ys.idxOfNth xs[i] (xs.countBefore xs[i] i)

theorem Subperm.getElem_idxInj_eq_getElem [BEq α] [LawfulBEq α] {xs ys : List α}
    (h : xs <+~ ys) {i : Fin xs.length} :
  ys[(h.idxInj i : Nat)] = xs[(i : Nat)]

theorem Subperm.idxInj_inj [BEq α] [LawfulBEq α] {xs ys : List α}
    {h : xs <+~ ys} (i j : Fin xs.length) :
  h.idxInj i = h.idxInj j ↔ i = j

public theorem toFinDigitsFixed_succ [NeZero base] :
    toFinDigitsFixed n base (prec+1) =
      toFinDigitsFixed (n / base) base prec ++ [Fin.ofNat base n]

public theorem toFinDigits_eq_append (h : 2 ≤ base) [NeZero base] (hk : base ^ k ≤ n) :
    toFinDigits n base =
      toFinDigits (n / base ^ k) base ++ toFinDigitsFixed (n % base ^ k) base k

theorem keysOrdered_iff_pairwise {α : Type u} {β : Type v} {cmp : α → α → Ordering}
    [TransCmp cmp] {l : AssocList α β} :
    KeysOrdered cmp l ↔ l.toList.Pairwise (fun p q : α × β => cmp p.1 q.1 = .lt)

theorem KeysOrdered.cons {cmp : α → α → Ordering}
    (w : LTHeadKey cmp a t) (h : KeysOrdered cmp t) :
    KeysOrdered cmp (.cons a b t)

theorem KeysOrdered.orderedInsert_aux [LawfulEqCmp cmp] [OrientedCmp cmp] {x y t}
    (h : KeysOrdered cmp (AssocList.cons x y t)) (w : cmp a x = Ordering.gt) :
    KeysOrdered cmp (AssocList.cons x y (AssocList.orderedInsert cmp t a b))

theorem getElem?_merge {f : α → Option β → Option γ → Option δ}
    (hf : f a none none = none) {l₁ : OrderedAssocList cmp β} {l₂} :
    (merge f l₁ l₂)[a]? = f a l₁[a]? l₂[a]?

theorem utf8PrevAux_of_valid {cs cs' : List Char} {c : Char} {i p : Nat}
    (hp : i + (utf8Len cs + c.utf8Size) = p) :
    Pos.Raw.utf8PrevAux (cs ++ c :: cs') ⟨i⟩ ⟨p⟩ = ⟨i + utf8Len cs⟩

theorem setParentBump_rankD_lt {arr : Array UFNode} {x y : Fin arr.size}
    (hroot : arr[x.1].rank < arr[y.1].rank ∨ arr[y.1].parent = y)
    (H : arr[x.1].rank ≤ arr[y.1].rank) {i : Nat}
    (rankD_lt : parentD arr i ≠ i → rankD arr i < rankD arr (parentD arr i))
    (hP : parentD arr' i = if x.1 = i then y.1 else parentD arr i)
    (hR : ∀ {i}, rankD arr' i =
      if y.1 = i ∧ arr[x.1].rank = arr[y.1].rank then
        arr[y.1].rank + 1
      else rankD arr i) :
    ¬parentD arr' i = i → rankD arr' i < rankD arr' (parentD arr' i)

theorem setParent_rankD_lt {arr : Array UFNode} {x y : Fin arr.size}
    (h : arr[x.1].rank < arr[y.1].rank) {i : Nat}
    (rankD_lt : parentD arr i ≠ i → rankD arr i < rankD arr (parentD arr i)) :
    let arr' := arr.set x ⟨y, arr[x].rank⟩
    parentD arr' i ≠ i → rankD arr' i < rankD arr' (parentD arr' i)

